import java.util.*;
public class Main { static class Facility { String[][] s; Facility(int... n){s=new String[n.length][];for(int i=0;i<n.length;i++)s[i]=new String[n[i]];} int[] allocate(String v){for(int f=0;f<s.length;f++)for(int i=0;i<s[f].length;i++)if(s[f][i]==null){s[f][i]=v;return new int[]{f,i};}return null;} boolean release(int f,int i){if(f<0||f>=s.length||i<0||i>=s[f].length||s[f][i]==null)return false;s[f][i]=null;return true;} } public static void main(String[]x){Facility p=new Facility(2,1);System.out.println(Arrays.toString(p.allocate("TN01")));System.out.println(Arrays.toString(p.allocate("TN02")));System.out.println(Arrays.toString(p.allocate("TN03")));System.out.println(p.allocate("TN04"));System.out.println(p.release(0,1));} }
